// Animated border that transforms from left to right or top to bottom when in view, with arrow icon control for direction and full Framer animation control. Only triggers on layer in view.
import { useRef, useEffect, useState, startTransition } from "react"
import { addPropertyControls, ControlType, useIsStaticRenderer } from "framer"

interface BorderRevealProps {
    direction: "leftToRight" | "topToBottom"
    transition: any
    borderColor: string
    size: number
    borderRadius: number
    replay: boolean
    style?: React.CSSProperties
}

/**
 * BorderReveal
 *
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight fixed
 */
export default function BorderReveal(props: BorderRevealProps) {
    const {
        direction = "leftToRight",
        transition = {
            type: "tween",
            ease: "easeInOut",
            duration: 0.7,
            delay: 0,
        },
        borderColor,
        size,
        borderRadius,
        replay = false,
        style,
    } = props
    const ref = useRef<HTMLDivElement>(null)
    const [inView, setInView] = useState(false)
    const [hasAnimated, setHasAnimated] = useState(false)
    const isStatic = useIsStaticRenderer()

    useEffect(() => {
        if (isStatic) {
            setInView(true)
            return
        }
        const node = ref.current
        if (!node) return
        let observer: IntersectionObserver | null = null
        observer = new window.IntersectionObserver(
            ([entry]) => {
                if (replay) {
                    startTransition(() => setInView(entry.isIntersecting))
                } else {
                    if (entry.isIntersecting && !hasAnimated) {
                        startTransition(() => setInView(true))
                        setHasAnimated(true)
                    }
                }
            },
            {
                threshold: 0,
            }
        )
        observer.observe(node)
        return () => {
            if (observer && node) observer.unobserve(node)
        }
    }, [isStatic, replay, hasAnimated])

    return (
        <div
            ref={ref}
            style={{
                ...style,
                position: "relative",
                width: direction === "leftToRight" ? "100%" : size,
                height: direction === "leftToRight" ? size : "100%",
                minWidth: 5,
                minHeight: 5,
                overflow: "hidden",
                borderRadius,
                background: "transparent",
            }}
        >
            <div
                style={{
                    position: "absolute",
                    left: direction === "leftToRight" ? 0 : undefined,
                    top: direction === "topToBottom" ? 0 : undefined,
                    width: direction === "leftToRight" ? (inView ? "100%" : 0) : size,
                    height: direction === "topToBottom" ? (inView ? "100%" : 0) : size,
                    background: borderColor,
                    borderRadius,
                    transition:
                        transition.type === "tween"
                            ? `${direction === "leftToRight" ? "width" : "height"} ${transition.duration ?? 0.7}s ${transition.ease === "linear" ? "linear" : transition.ease === "easeIn" ? "cubic-bezier(0.4,0,1,1)" : transition.ease === "easeOut" ? "cubic-bezier(0,0,0.2,1)" : transition.ease === "easeInOut" ? "cubic-bezier(0.4,0,0.2,1)" : "cubic-bezier(0.4,0,0.2,1)"} ${transition.delay ?? 0}s`
                            : transition.type === "spring"
                              ? undefined
                              : undefined,
                }}
                aria-hidden="true"
            />
        </div>
    )
}

addPropertyControls(BorderReveal, {
    direction: {
        type: ControlType.Enum,
        title: "Direction",
        options: ["leftToRight", "topToBottom"],
        optionTitles: ["→", "↓"],
        defaultValue: "leftToRight",
        displaySegmentedControl: true,
    },
    replay: {
        type: ControlType.Boolean,
        title: "Replay",
        defaultValue: false,
        enabledTitle: "Yes",
        disabledTitle: "No",
    },
    transition: {
        type: ControlType.Transition,
        title: "Animation",
    },
    borderColor: {
        type: ControlType.Color,
        title: "Border Color",
        defaultValue: "#222",
    },
    size: {
        type: ControlType.Number,
        title: "Size",
        defaultValue: 4,
        min: 1,
        max: 40,
        step: 1,
        unit: "px",
    },
    borderRadius: {
        type: ControlType.Number,
        title: "Radius",
        defaultValue: 2,
        min: 0,
        max: 20,
        step: 1,
        unit: "px",
    },
})
